            metadata(clip, node, scene.viewport.id);
            reportAssetFallback(clip, node, clipAsset, scene.viewport.id, options);
            shapes.set(node.id, clip);
            for (const child of childrenByParent.get(node.id) || []) await render(child, clip);
            reportProgress();
            return clip;
